'use strict';
const E=window.ScoreEngine,$=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),nf=new Intl.NumberFormat('sv-SE',{maximumFractionDigits:1}),pf=new Intl.NumberFormat('sv-SE',{maximumFractionDigits:0}),query=new URLSearchParams(location.search);let historyModels=[],input,model,sortKey='rank',ascending=true,previousModel,custom={...E.DEFAULT_WEIGHTS};
try{const saved=JSON.parse(localStorage.getItem('sverige-score-weights-v1')||'null');if(saved)custom=Object.fromEntries(E.THEMES.map(t=>[t.id,Math.min(100,Math.max(0,Number(saved[t.id]??t.weight)||0))]));}catch{}
// Ten selectable importance levels, including zero. Five internal weight units
// per level preserve the existing 20/15/10 standard proportions exactly.
const IMPORTANCE_MAX=9,IMPORTANCE_UNIT=5;
const savedScale=Math.max(...Object.values(custom))>IMPORTANCE_MAX*IMPORTANCE_UNIT?IMPORTANCE_MAX*IMPORTANCE_UNIT/Math.max(...Object.values(custom)):1;
const initialLevels=Object.fromEntries(E.THEMES.map(t=>[t.id,Math.min(IMPORTANCE_MAX,Math.max(0,Math.round(custom[t.id]*savedScale/IMPORTANCE_UNIT)))]));
const importanceText=n=>n===0?'Oviktigt':n===IMPORTANCE_MAX?'Viktigt':'Nivå '+(n+1)+' av 10';
const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('sv');
$('weights').innerHTML=E.THEMES.map(t=>'<label class="weight" for="w-'+t.id+'">'+esc(t.label)+'<input id="w-'+t.id+'" type="range" min="0" max="9" step="1" list="importanceLevels" aria-describedby="wn-'+t.id+'" value="'+initialLevels[t.id]+'"><span class="importance-ends" aria-hidden="true"><span>Oviktigt</span><span>Viktigt</span></span><small id="wn-'+t.id+'"></small></label>').join('');
$('year').innerHTML='';$('year').disabled=true;$('search').value=query.get('q')||'';
function details(row){const parts=row.themes.map(t=>{const metrics=t.metrics.map(m=>{const spec=E.METRICS[m.id],meta=input.metadata[spec.keys[0]],source=spec.keys.map(k=>input.metadata[k]?.source||k).filter((v,i,a)=>a.indexOf(v)===i).join(' / '),value=m.value==null?'Uppgift saknas':nf.format(m.value)+' '+spec.unit,reason=m.value!=null&&m.points==null?' · för få kommuner med uppgift':'';return '<li><strong>'+esc(spec.label)+'</strong>: '+esc(value)+(m.period?' · '+(meta?.periods?.[m.year]?'mätperiod ':'redovisningsår ')+esc(m.period):'')+(m.points!=null?' · delpoäng '+nf.format(m.points)+' av 100':'')+reason+'<br>Källa: '+esc(source)+(meta?.url?' · <a target="_blank" rel="noopener" href="'+esc(meta.url)+'">Originalkälla</a>':'')+(meta?.definition?'<details><summary>Definition</summary>'+esc(meta.definition)+'</details>':'')+'</li>';}).join('');return '<div class="theme"><strong>'+esc(t.label)+' · '+(t.score==null?'saknar poäng':nf.format(t.score)+' / 100')+'</strong><small>Vikt '+pf.format(model.weights[t.id]*100)+' % · underlag '+pf.format(t.coverage*100)+' %</small><ul>'+metrics+'</ul></div>';}).join('');const prev=previousModel?.rows.find(r=>r.code===row.code);let movement='';if(row.eligible&&prev?.eligible){const delta=row.score-prev.score;movement='<p>Poängskillnad mot '+previousModel.year+': '+(delta>0?'+':'')+nf.format(delta)+'. Det är en ändring i jämförelsepoängen. Den visar inte säkert att vardagen blivit bättre eller sämre.</p>';}return '<div class="breakdown">'+parts+movement+'<a href="/focus/?municipality='+encodeURIComponent(row.code)+'&year='+model.year+'">Öppna kommunens fokusvy</a></div>';}
function filtered(){const q=normalize($('search').value.trim());return model.rows.filter(r=>!q||normalize(r.name+' '+r.code).includes(q)).slice().sort((a,b)=>{if(sortKey==='name')return (ascending?1:-1)*a.name.localeCompare(b.name,'sv');if(a.eligible!==b.eligible)return a.eligible?-1:1;const x=sortKey==='rank'?a.rank:a.score,y=sortKey==='rank'?b.rank:b.score;return ((x??Infinity)-(y??Infinity))*(ascending?1:-1)||a.name.localeCompare(b.name,'sv');});}
function render(){if(!model)return;const rows=filtered();$('rows').innerHTML=rows.length?rows.map(r=>'<tr role="row"><td role="cell">'+(r.rank??'—')+'</td><td role="cell"><a class="name" href="/focus/?municipality='+r.code+'&year='+model.year+'">'+esc(r.name)+'</a><small>'+esc(r.code)+'</small></td><td role="cell"><span class="score">'+(r.score==null?'—':nf.format(r.score))+'</span><small>'+pf.format(r.coverage*100)+' % underlag</small>'+window.scoreChart(historyModels.map(h=>({year:h.year,score:h.rows.find(p=>p.code===r.code)?.score??null})),model.year)+'</td><td role="cell"><p class="comment">'+esc(r.comment)+'</p>'+'<details class="rowdetail" data-score-details="'+r.code+'"><summary>Visa poäng, år och källor för '+esc(r.name)+'</summary><div data-score-body></div></details></td></tr>').join(''):'<tr role="row"><td colspan="4" class="empty">Ingen kommun matchar sökningen.</td></tr>';document.querySelectorAll('[data-score-details]').forEach(el=>el.ontoggle=()=>{if(el.open&&!el.dataset.loaded){el.querySelector('[data-score-body]').innerHTML=details(model.rows.find(r=>r.code===el.dataset.scoreDetails));el.dataset.loaded='yes';}});$('resultSummary').textContent=rows.length+' av '+model.rows.length+' kommuner visas. '+model.ranked+' har tillräckligt underlag för placering år '+model.year+'. Placeringarna gäller alla kommuner, även när du söker.';document.querySelectorAll('th[aria-sort]').forEach(th=>th.removeAttribute('aria-sort'));document.querySelector('[data-sort="'+sortKey+'"]').closest('th').setAttribute('aria-sort',ascending?'ascending':'descending');}
function calculate(){if(!input)return;custom=Object.fromEntries(E.THEMES.map(t=>[t.id,Number($('w-'+t.id).value)*IMPORTANCE_UNIT]));for(const t of E.THEMES){const level=Number($('w-'+t.id).value);$('w-'+t.id).setAttribute('aria-valuetext',importanceText(level));$('wn-'+t.id).textContent=importanceText(level);}try{const requested=Number($('year').value||query.get('year'));historyModels=Array.from({length:(input.maxYear||2026)-2010+1},(_,i)=>E.build(input,2010+i,custom)).filter(h=>h.ranked>0);$('year').innerHTML=historyModels.slice().reverse().map(h=>'<option>'+h.year+'</option>').join('');$('year').disabled=!historyModels.length;if(!historyModels.length)throw Error('Inga år har tillräckligt underlag med dessa vikter.');model=historyModels.find(h=>h.year===requested)||historyModels[historyModels.length-1];$('year').value=String(model.year);previousModel=historyModels.filter(h=>h.year<model.year).at(-1)||null;$('error').hidden=true;$('downloadCsv').disabled=false;for(const t of E.THEMES)$('wn-'+t.id).textContent=importanceText(Number($('w-'+t.id).value))+' · vikt '+pf.format(model.weights[t.id]*100)+' %';try{localStorage.setItem('sverige-score-weights-v1',JSON.stringify(custom));}catch{}render();}catch(e){model=null;$('error').hidden=false;$('error').textContent=Object.values(custom).every(v=>v===0)?'Flytta minst ett reglage åt höger.':e.message;$('rows').innerHTML='';$('resultSummary').textContent='Ingen poäng räknas med detta val.';$('downloadCsv').disabled=true;}}
$('search').oninput=render;$('year').onchange=calculate;E.THEMES.forEach(t=>{$('w-'+t.id).oninput=calculate;$('w-'+t.id).onchange=calculate;});$('resetWeights').onclick=()=>{E.THEMES.forEach(t=>$('w-'+t.id).value=t.weight/IMPORTANCE_UNIT);calculate();};document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{if(sortKey===b.dataset.sort)ascending=!ascending;else {sortKey=b.dataset.sort;ascending=sortKey!=='score';}render();});
$('downloadCsv').onclick=()=>{if(!model)return;const cell=v=>'"'+String(v??'').replace(/^[=+@\-]/,"'").replace(/"/g,'""')+'"';const text='\ufeff'+[['Plats','Kommun','Score','Kommentar','Underlag (%)','År','Metod','Utgåva','Vikter'],...filtered().map(r=>[r.rank,r.name,r.score,r.comment,Math.round(r.coverage*100),model.year,model.version,input.revision,JSON.stringify(custom)])].map(r=>r.map(cell).join(';')).join('\r\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='kommunpoang-'+model.year+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
fetch('/data/score-input.json').then(r=>{if(!r.ok)throw Error('Poängunderlaget kunde inte hämtas. Försök ladda om sidan.');return r.json();}).then(d=>{input=d;$('revision').textContent='Metod '+E.VERSION+' · datautgåva '+d.revision+'.';$('methodMetrics').innerHTML='<table class="methodtable"><thead><tr><th>Område</th><th>Mått som ingår</th></tr></thead><tbody>'+E.THEMES.map(t=>'<tr><th>'+esc(t.label)+'</th><td>'+t.metrics.map(id=>esc(E.METRICS[id].label)+(E.METRICS[id].direction<0?' (lägre ger högre poäng)':' (högre ger högre poäng)')).join('<br>')+'</td></tr>').join('')+'</tbody></table>';calculate();}).catch(e=>{$('error').hidden=false;$('error').textContent=e.message;$('resultSummary').textContent='Underlaget kunde inte läsas.';});
fetch('/data/score-revisions.json').then(r=>r.json()).then(rs=>{$('historyLinks').innerHTML=rs.slice().reverse().map(r=>'<p><a download href="'+esc(r.file)+'">Sparat standardresultat · '+esc(r.revision)+' · metod '+esc(r.methodVersion)+'</a></p>').join('');}).catch(()=>{});
